"""
import json
import os
import re
import subprocess
import sys
from collections import Counter, defaultdict
from pathlib import Path

REPO = Path("~/leveraged-etf-risk-analytics")
HOME = Path.home()
ROOTS = [Path(p) for p in sys.argv[1:]]
THIS = re.compile(r"^(etf-risk-jobs|docker)[-_]")
SERVICES = {"mysql", "kafka", "redis", "zookeeper", "spark"}
DOCKER = re.compile(r"\bdocker\b")


def committed(v):
    return subprocess.run(["git", "-C", str(REPO), "grep", "-q", "-F", "-e", v, "origin/main", "--", ":!docs/ai-usage"]).returncode == 0


def strings(o):
    if isinstance(o, str):
        yield o
    elif isinstance(o, list):
        for v in o:
            yield from strings(v)
    elif isinstance(o, dict):
        for v in o.values():
            yield from strings(v)


def records(d):
    return [json.loads(l) for l in (d / "transcript.jsonl").read_bytes().decode("utf-8").split("\n") if l.strip()]


def tool_pairs(recs):
    uses, out = {}, []
    for r in recs:
        m = r.get("message") if isinstance(r.get("message"), dict) else {}
        for b in m.get("content") if isinstance(m.get("content"), list) else []:
            if not isinstance(b, dict):
                continue
            if b.get("type") == "tool_use":
                uses[b.get("id")] = (b.get("name"), b.get("input") or {})
            elif b.get("type") == "tool_result":
                name, inp = uses.get(b.get("tool_use_id"), ("?", {}))
                res = "\n".join(strings(b.get("content")))
                extra = "\n".join(strings(r.get("toolUseResult")))
                out.append((name, inp, res + "\n" + extra))
    return out


def docker_kind(cmd):
    for k in ("compose ls", "compose ps", "volume ls", "network ls", "stats", "images", "ps", "inspect", "logs"):
        if re.search(r"docker (?:compose[^|;&]* )?" + re.escape(k).replace(r"\ ", r"\s+") + r"\b", cmd):
            return k
    return "other docker"


containers = Counter()
other_names = set()
for root in ROOTS:
    for d in sorted(p for p in root.iterdir() if p.is_dir() and (p / "transcript.jsonl").is_file()):
        for name, inp, res in tool_pairs(records(d)):
            cmd = str(inp.get("command", ""))
            if not DOCKER.search(cmd):
                continue
            kind = docker_kind(cmd)
            lines = res.splitlines()
            header = None
            for line in lines:
                cols = re.split(r"\s{2,}", line.strip())
                if any(c in ("NAMES", "NAME", "CONTAINER ID", "SERVICE", "VOLUME NAME", "IMAGE", "STATUS") for c in cols):
                    header = cols
                    continue
                for tok in set(re.findall(r"(?<![\w./:-])([a-z0-9][a-z0-9_.-]*[a-z][a-z0-9_.-]*[-_]\d+)(?![\w.-])", line)):
                    if THIS.match(tok) or committed(tok):
                        continue
                    col = "?"
                    if header:
                        cols = re.split(r"\s{2,}", line.strip())
                        if tok in cols and len(cols) == len(header):
                            col = header[cols.index(tok)]
                        elif cols and cols[-1] == tok and header[-1] == "NAMES":
                            col = "NAMES"
                    containers[(kind, col)] += 1
                    other_names.add(tok)
print("== container-like tokens not from this project, by docker command and column (occurrences)")
for (kind, col), n in sorted(containers.items()):
    print(f"  {n:4d}  {kind} | column {col}")
print(f"  distinct tokens: {len(other_names)}; with a stack service in the name: {sum(1 for t in other_names if set(re.split(r'[-_.]', t)) & SERVICES)}")

out = os.environ.get("REVIEW_OUT")
if out:
    with open(out, "w") as fh:
        json.dump({"containers": sorted(other_names)}, fh)
    os.chmod(out, 0o600)

