import json, re, sys
from collections import Counter, defaultdict
from pathlib import Path
toks = json.load(open(sys.argv[1]))["containers"]
root = Path(sys.argv[2])
texts = {d.name: (d / "transcript.jsonl").read_bytes().decode() for d in root.iterdir() if d.is_dir()}
prefix = lambda t: "-".join(re.split(r"[-_]", t)[:-2]) if len(re.split(r"[-_]", t)) >= 3 else ""
groups = Counter(prefix(t) for t in toks if prefix(t))
rows = Counter()
for t in toks:
    shape = re.sub(r"[a-z]", "a", re.sub(r"[0-9]", "9", t))
    folders = sum(1 for x in texts.values() if t in x)
    ctx = set()
    for x in texts.values():
        for line in x.replace("\\n", "\n").splitlines():
            if t in line:
                if re.search(r"\b(Up|Exited|Created|Restarting|Paused)\b", line): ctx.add("container row")
                elif re.search(r"MiB|GiB|%", line): ctx.add("stats row")
                elif re.search(r"\blocal\b", line): ctx.add("volume row")
                else: ctx.add("other line")
    shared = "shares a project prefix" if prefix(t) and groups[prefix(t)] > 1 else ("compose-style" if prefix(t) else "two-part")
    rows[(shape, shared, "+".join(sorted(ctx)), folders)] += 1
for (shape, shared, ctx, folders), n in sorted(rows.items(), key=lambda kv: (kv[0][2], kv[0][0])):
    print(f"{n:2d} x {shape:32s} {shared:25s} {ctx:45s} in {folders} folders")
print("project prefixes shared by 2+ tokens:", sum(1 for g, n in groups.items() if n > 1), "| largest group size:", max(groups.values()) if groups else 0)
EOF

